(() => {
 const $=id=>document.getElementById(id),L=window.SACCR_LESSONS,esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let active=0,state={},result;
 const format=(v,d)=>d.unit==='£m'?'£'+Number(v).toFixed(d.step<1?2:0)+'m':v+(d.unit?' '+d.unit:'');
 function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
 function chart(r){const width=Math.max(330,Math.min(800,$('chart').clientWidth||740));let svg=`<title>${esc(L[active].chart)}</title>`;if(r.bars){const data=r.bars,height=Math.max(250,data.length*37+45),left=width<450?105:155,right=width-65,lo=Math.min(0,...data.map(d=>d.value)),hi=Math.max(.01,...data.map(d=>d.value)),span=hi-lo||1,x=v=>left+(v-lo)/span*(right-left);$('chart').setAttribute('viewBox',`0 0 ${width} ${height}`);data.forEach((d,i)=>{const y=30+i*(height-60)/data.length;svg+=`<text x="${left-10}" y="${y+15}" text-anchor="end">${esc(d.label)}</text><rect x="${Math.min(x(0),x(d.value))}" y="${y}" width="${Math.max(.5,Math.abs(x(d.value)-x(0)))}" height="22" rx="3" fill="${d.color||'#285e46'}"/><text x="${d.value<0?x(d.value)-5:x(d.value)+5}" y="${y+15}" text-anchor="${d.value<0?'end':'start'}">${Number(d.value).toFixed(2)}</text>`});svg+=`<line x1="${x(0)}" x2="${x(0)}" y1="18" y2="${height-28}" stroke="#b0c6b7"/>`;}
 else {const w=width-35,left=55,top=22,bottom=255,all=r.series.flatMap(s=>s.data),xmin=r.x?.[0]??Math.min(...all.map(p=>p[0])),xmax=r.x?.[1]??Math.max(...all.map(p=>p[0])),ymin=r.y?.[0]??Math.min(0,...all.map(p=>p[1])),ymax=r.y?.[1]??Math.max(.01,...all.map(p=>p[1])),X=v=>left+(v-xmin)/(xmax-xmin||1)*(w-left),Y=v=>bottom-(v-ymin)/(ymax-ymin||1)*(bottom-top);$('chart').setAttribute('viewBox',`0 0 ${width} 310`);for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4,x=xmin+(xmax-xmin)*i/4;svg+=`<line x1="${left}" x2="${w}" y1="${Y(y)}" y2="${Y(y)}" stroke="#e0e9e1"/><text x="${left-8}" y="${Y(y)+4}" text-anchor="end">${y.toFixed(1)}</text><text x="${X(x)}" y="278" text-anchor="middle">${x.toFixed(0)}</text>`}r.series.forEach(s=>{if(s.dots){svg+=s.data.map(([x,y])=>`<circle cx="${X(x)}" cy="${Y(y)}" r="2.2" fill="${s.color}" opacity=".65"/>`).join('')}else svg+=`<path d="${s.data.map(([x,y],i)=>`${i?'L':'M'}${X(x).toFixed(2)},${Y(y).toFixed(2)}`).join(' ')}" stroke="${s.color}" fill="none" stroke-width="2.3"/>`});svg+=`<text x="${width/2}" y="303" text-anchor="middle">${esc(r.xlabel||'Scenario')}</text>`;}
 $('chart').innerHTML=svg;$('chart').setAttribute('aria-label',L[active].chart+'. '+r.explanation);$('legend').innerHTML=(r.series||[]).map(s=>`<span style="--c:${s.color}">${esc(s.name)}</span>`).join('');}
 function update(){const l=L[active];result=l.compute(state);$('stats').innerHTML=result.stats.map(([a,b])=>`<div class="stat"><label>${esc(a)}</label><strong>${esc(b)}</strong></div>`).join('');chart(result);$('explanation').textContent=result.explanation;$('chart-note').textContent=result.note||'';$('trace').innerHTML=table(result.headers,result.rows);$('formula').textContent=result.formula||l.formula;$('formula-key').textContent=result.key||l.key;document.querySelectorAll('[data-control]').forEach(el=>{const d=l.inputs.find(d=>d.id===el.dataset.control);el.hidden=!!d.when&&!d.when(state)});}
 function render(){const l=L[active];let group='';$('lessons').innerHTML=L.map((x,i)=>{const title=group===x.stage?'':`<div class="nav-group">${esc(x.stage)}</div>`;group=x.stage;return title+`<button data-lesson="${i}" class="${active===i?'active':''}" ${active===i?'aria-current="step"':''}><b>${i+1}</b><span>${esc(x.name)}</span></button>`}).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>select(+b.dataset.lesson));for(const [id,value]of Object.entries({level:l.stage,title:l.title,intro:l.intro,count:`${active+1} / ${L.length} APPLETS`,'chart-title':l.chart,challenge:l.challenge,'simple-title':l.simpleTitle,simple:l.simple,scope:l.scope}))$(id).textContent=value;
 $('inputs').innerHTML=l.inputs.map(d=>`<div class="input" data-control="${d.id}">${d.options?`<label for="f-${d.id}">${esc(d.label)}</label><select id="f-${d.id}">${d.options.map(([v,label])=>`<option value="${esc(v)}" ${String(state[d.id])===String(v)?'selected':''}>${esc(label)}</option>`).join('')}</select>`:`<div class="input-top"><label for="f-${d.id}">${esc(d.label)}</label><output class="value" id="value-${d.id}" for="f-${d.id}">${esc(format(state[d.id],d))}</output></div><input type="range" id="f-${d.id}" min="${d.min}" max="${d.max}" step="${d.step}" value="${state[d.id]}" aria-valuetext="${esc(format(state[d.id],d))}"><div class="bounds"><span>${esc(format(d.min,d))}</span><span>${esc(format(d.max,d))}</span></div>`}</div>`).join('');l.inputs.forEach(d=>$('f-'+d.id).oninput=e=>{state[d.id]=d.options?e.target.value:+e.target.value;if(!d.options){$('value-'+d.id).textContent=format(state[d.id],d);e.target.setAttribute('aria-valuetext',format(state[d.id],d))}update()});
 $('notes').innerHTML=(l.notes||[]).map(([title,body])=>`<details><summary>${esc(title)}</summary><p>${esc(body)}</p></details>`).join('')+(l.reference?`<details><summary>Prescribed parameters · reference table</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Supervisory parameters">${table(l.reference.headers,l.reference.rows)}</div></details>`:'');$('reading').innerHTML=l.sources.map(([url,label])=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)}</a>`).join(' · ');$('learning').innerHTML='';window.renderLearning(l.id);$('next').textContent=active===L.length-1?'Return to exposure foundations ↺':'Next concept →';document.title=l.name+' — SA-CCR · Quant$ense';update();}
 function select(i,hash=true){active=i;state=Object.fromEntries(L[i].inputs.map(d=>[d.id,d.value]));render();if(hash)history.replaceState(null,'','#'+L[i].id)}
 $('reset').onclick=()=>select(active);$('next').onclick=()=>select((active+1)%L.length);window.addEventListener('hashchange',()=>{const i=L.findIndex(l=>l.id===location.hash.slice(1));if(i>=0)select(i,false)});window.addEventListener('resize',()=>chart(result));const i=L.findIndex(l=>l.id===location.hash.slice(1));select(i<0?0:i,false);
 window.SACCR_APP={getState:()=>({lesson:L[active].id,values:{...state},stats:result.stats}),configure(input){const i=L.findIndex(l=>l.id===input.lesson);if(i<0)throw Error('Unknown lesson');for(const [k,v]of Object.entries(input.values||{})){const d=L[i].inputs.find(d=>d.id===k);if(!d||(d.options?!d.options.some(o=>o[0]===v):!Number.isFinite(v)||v<d.min||v>d.max||Math.abs((v-d.min)/d.step-Math.round((v-d.min)/d.step))>1e-6))throw Error('Invalid control: '+k)}select(i);Object.assign(state,input.values||{});render();return this.getState()}};
 if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_saccr_applet',description:'Select an SA-CCR lesson and set its visible educational controls; returns the same results shown on the page.',inputSchema:{type:'object',properties:{lesson:{type:'string',enum:L.map(l=>l.id)},values:{type:'object',additionalProperties:{type:['string','number']}}},required:['lesson'],additionalProperties:false},execute:input=>window.SACCR_APP.configure(input)})).catch(()=>{})}catch{}}
})();
